package com.clothingstore;
import org.springframework.context.annotation.*; import org.springframework.security.config.Customizer; import org.springframework.security.config.annotation.web.builders.HttpSecurity; import org.springframework.security.config.http.SessionCreationPolicy; import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.security.web.*; import org.springframework.security.web.authentication.UsernamePasswordAuthenticationFilter;
@Configuration public class SecurityConfig { private final JwtAuthFilter jwtFilter; SecurityConfig(JwtAuthFilter jwtFilter){this.jwtFilter=jwtFilter;} @Bean PasswordEncoder passwordEncoder(){return new BCryptPasswordEncoder();} @Bean SecurityFilterChain securityFilterChain(HttpSecurity http)throws Exception{return http.csrf(csrf->csrf.disable()).cors(Customizer.withDefaults()).sessionManagement(session->session.sessionCreationPolicy(SessionCreationPolicy.STATELESS)).authorizeHttpRequests(auth->auth.requestMatchers("/api/v1/auth/**","/api/v1/products","/api/v1/health").permitAll().requestMatchers("/api/v1/admin/**").hasRole("ADMIN").anyRequest().permitAll()).addFilterBefore(jwtFilter,UsernamePasswordAuthenticationFilter.class).build();} }
